Script for testing:
```ts
import { Squid } from "@0xsquid/sdk";
import {
  SigningStargateClient,
} from "@cosmjs/stargate";
import {
  DirectSecp256k1HdWallet,
  OfflineDirectSigner,
} from "@cosmjs/proto-signing";

import { SlippageMode } from "@0xsquid/sdk/dist/types";
import { TxRaw } from "cosmjs-types/cosmos/tx/v1beta1/tx";

(async () => {
  const baseUrl = "http://localhost:3000";
  const squid = new Squid({
    baseUrl: baseUrl,
    integratorId: "pipi",
  });
  await squid.init();
  console.log("Squid inited");

  const mnemonic =
    "<put memo here>";
  const rpc = "https://noble-rpc.polkachu.com";

  const getSignerFromMnemonic = async (): Promise<OfflineDirectSigner> => {
    return DirectSecp256k1HdWallet.fromMnemonic(mnemonic, {
      prefix: "noble",
    });
  };
  const offlineSigner: OfflineDirectSigner = await getSignerFromMnemonic();

  const signerAddress = (await offlineSigner.getAccounts())[0].address;

  const signingClient = await SigningStargateClient.connectWithSigner(
    rpc,
    offlineSigner
  );

  console.log("balances: ", await signingClient.getAllBalances(signerAddress));


  const route = await squid.getRoute({
    fromChain: "noble-1",
    fromToken: "uusdc",
    fromAmount: "1000000",
    toChain: "1",
    toToken: "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48",
    fromAddress: signerAddress,
    toAddress: "0x747A6e3824FAB0d1266306C3b492fcB941C5dd93",
    slippageConfig: {
      slippage: 1.5,
      autoMode: SlippageMode.NORMAL,
    },
  });
  console.log("Got route");

  const tx = await squid.executeRoute({
    signer: signingClient,
    route: route.route,
    signerAddress,
  }) as TxRaw;

  const cosmosTx = await signingClient.broadcastTx(
    TxRaw.encode(tx).finish()
  );

  console.log(cosmosTx.transactionHash);
})();
```
